code.source:
App [
    reveal: AnimatorGroup [ process = sequential, duration = 200,
        Animator [ attribute = opacity, to = 1 ],
        Animator [ attribute = y,       to = 0 ]
        ]
]

App [
    dot: View [ width = 10, height = 10, cornerRadius = 5, fill = turquoise,
        followX: Spring [ attribute = x, to = { app.pointerX - 5 },
            stiffness = 120, damping = 14, mass = 0.6 ]
        ]
]

App [ width = 240, height = 120, fill = midnightblue, textColor = whitesmoke,
    x0: number = 20,
    v: number = 60,
    physics: Heartbeat [ onFrame(dt: number) { app.x0 = (app.x0 + app.v * dt) % 200 }
        ],
    dot: View [ x = { app.x0 }, y = 40, width = 40, height = 40, cornerRadius = 20,
        fill = turquoise ]
    ]

App [ width = 240, height = 100, fill = white, textColor = black,
    n: number = 0,
    keys: Keys [
        onKeyUp(e: KeyEvent) {
            if (e.key == "ArrowUp") { app.n = app.n + 1 }
            else if (e.key == "ArrowDown") { app.n = app.n - 1 }
            }
        ],
    Text [ x = 20, y = 30, fontSize = 30, text = { `n = ${n}` } ]
    ]

